import{_ as s,c as t,o as e,H as n}from"./chunks/framework.B03ETCDl.js";const m=JSON.parse('{"title":"KDB+ 시계열 데이터베이스","description":"","frontmatter":{"title":"KDB+ 시계열 데이터베이스","date":"2024-10-24T21:00+09:00","tags":["KDB+","Performance"]},"headers":[],"relativePath":"posts/kdb-plus.md","filePath":"posts/kdb-plus.md","lastUpdated":1779921860000}'),p={name:"posts/kdb-plus.md"};function l(i,a,r,d,o,c){return e(),t("div",null,[...a[0]||(a[0]=[n(`<p>KDB+는 벡터 기반의 언어를 제공하며 높은 성능을 제공하는 시계열 데이터베이스를 조금 더 활용할 수 있는 방안을 알아보자.</p><h4 id="병렬-처리를-위한-보조-스레드" tabindex="-1">병렬 처리를 위한 보조 스레드 <a class="header-anchor" href="#병렬-처리를-위한-보조-스레드" aria-label="Permalink to &quot;병렬 처리를 위한 보조 스레드&quot;">​</a></h4><p>KDB+는 기본적으로 싱글 코어와 싱글 스레드 기반으로 동작한다. 병렬 처리(Parallel Processing)는 별도의 보조 스레드에 의해 수행된다. 보조 스레드는 KDB+ 프로세스 실행 시 <code>-s</code> 옵션으로 지정하며 메인 스레드와 보조 스레드간 통신은 IPC 직렬화를 수행하므로 오버헤드가 큰 작업에 해당되므로 사용중인 코어 수에 따라 적당한 보조 스레드를 구성해야한다. 또한, 프로세스 내에서 보조 스레드 수를 조정할 순 있지만 프로세스 실행 시 지정한 보조 스레드 수를 넘을 순 없음에 주의해야한다.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">q</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5555</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 12</span></span></code></pre></div><ul><li>Parallel Each – peach</li><li>Parallel on Cut – .Q.fc</li></ul><blockquote><p>다수의 파티션을 조회해야하는 HDB 프로세스는 보조 스레드를 두어 사용자 정의 함수에서 병렬 처리가 가능하도록 고려하세요.</p></blockquote><h4 id="파티션-수에-따른-디스크-성능-이슈" tabindex="-1">파티션 수에 따른 디스크 성능 이슈 <a class="header-anchor" href="#파티션-수에-따른-디스크-성능-이슈" aria-label="Permalink to &quot;파티션 수에 따른 디스크 성능 이슈&quot;">​</a></h4><p>관계형 데이터베이스에서 디스크 I/O 가 중요한 것처럼 KDB+ 에서도 일정 시간 범위에 대한 데이터를 조회하기 위하여 확인해야할 파티션의 수에 따라 디스크 I/O가 중요해진다. 예를 들어, 1시간 단위로 저장해놓은 파티션의 경우에 한달 범위에 대한 통계를 위해서 조회하고자 한다면 약 720개의 파티션 폴더를 조회해야하고 KDB+ 프로세스는 해당 폴더 액세스를 위해 디스크 볼륨에 의존할 수 밖에 없다. 이처럼 시계열 데이터베이스를 활용한다고 해도 하루에 저장되는 데이터 규모에 따라 파티션을 결정해야하는 것이 중요하다. KDB+ 에서는 다수의 디스크 볼륨을 사용할 수 있는 <a href="https://code.kx.com/q/database/segment/" target="_blank" rel="noreferrer">세그먼트</a>도 지원하는데 서로 다른 디스크 볼륨을 통해 병렬 액세스를 수행할 수 있다.</p><blockquote><p>Partition data correctly: data for a particular date must reside in the partition for that date.</p></blockquote><h5 id="조회-범위-별-소요-시간-비교" tabindex="-1">조회 범위 별 소요 시간 비교 <a class="header-anchor" href="#조회-범위-별-소요-시간-비교" aria-label="Permalink to &quot;조회 범위 별 소요 시간 비교&quot;">​</a></h5><table tabindex="0"><thead><tr><th>기준</th><th>조회 범위</th><th>시간별 파티션</th><th>일자별 파티션</th></tr></thead><tbody><tr><td>일별</td><td>한달</td><td>2.95s 🌀</td><td>30ms⭐️</td></tr><tr><td>주간</td><td>7일</td><td>50ms</td><td>40ms</td></tr><tr><td>월간</td><td>1년</td><td>40.79s 🔥</td><td>83ms⭐️</td></tr></tbody></table><blockquote><p>InfluxDB 또는 TimescaleDB 에서 <a href="https://docs.timescale.com/use-timescale/latest/continuous-aggregates/" target="_blank" rel="noreferrer">Continuous aggregates</a> 기능을 포함하고 있는 이유도 규모가 큰 데이터를 빠르게 조회하기 위함 입니다.</p></blockquote><h4 id="조회-성능을-향상시킬-수-있는-속성" tabindex="-1">조회 성능을 향상시킬 수 있는 속성 <a class="header-anchor" href="#조회-성능을-향상시킬-수-있는-속성" aria-label="Permalink to &quot;조회 성능을 향상시킬 수 있는 속성&quot;">​</a></h4><p>KDB+ 에서는 Sorted, Unique, Grouped, Parted 와 같은 <a href="https://code.kx.com/q/ref/set-attribute/" target="_blank" rel="noreferrer">속성(Attribute)</a>을 제공하여 쿼리에 대한 성능을 높일 수 있다. 관계형 데이터베이스에서 인덱스와 힌트라고 이해하면 될 것 같다.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/ apply attributes</span></span>
<span class="line"><span>meter_with_attr: 0!update \`s#id, \`p#name, \`g#timestamp from \`name xasc select from meter</span></span>
<span class="line"><span>meta meter_with_attr</span></span>
<span class="line"><span></span></span>
<span class="line"><span>| c         | t f a |</span></span>
<span class="line"><span>| --------- | ----- |</span></span>
<span class="line"><span>| date      | d     |</span></span>
<span class="line"><span>| id        | s   s |</span></span>
<span class="line"><span>| name      | s   p |</span></span>
<span class="line"><span>| timestamp | p   g |</span></span>
<span class="line"><span>| val       | f     |</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/ remove attributes</span></span>
<span class="line"><span>meter_with_attr:update \`#id,\`#name from meter_with_attr</span></span>
<span class="line"><span>meta meter_with_attr</span></span>
<span class="line"><span></span></span>
<span class="line"><span>| c         | t f a |</span></span>
<span class="line"><span>| --------- | ----- |</span></span>
<span class="line"><span>| date      | d     |</span></span>
<span class="line"><span>| id        | s     |</span></span>
<span class="line"><span>| name      | s     |</span></span>
<span class="line"><span>| timestamp | p   g |</span></span>
<span class="line"><span>| val       | f     |</span></span></code></pre></div><blockquote><p>파티션으로 저장된 테이블은 모든 파티션에 속성이 지정되어있어야 합니다. <a href="https://github.com/KxSystems/kdb/blob/master/utils/dbmaint.md#setattrcol" target="_blank" rel="noreferrer">dbmaint.setattrcol</a> 를 참고하세요.</p></blockquote><hr><p>벡터 DB에 대한 관심도가 높아지면서 <a href="https://kdb.ai/" target="_blank" rel="noreferrer">KDB.AI</a>는 AI를 위한 벡터 데이터베이스로 제공하는가 봅니다.</p>`,18)])])}const u=s(p,[["render",l]]);export{m as __pageData,u as default};
